join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P211', 'P229', 'P182', 'P058', 'P059', 'P114', 'P131', 'P187', 'P230', 'P231', 'P057', 'P080', 'P142', 'P185', 'P217', 'P224', 'P060', 'P132', 'P216', 'P092', 'P186')) <> 21 then
    raise exception 'a character of the ninth batch has no kit';
  end if;
end $$;
